def run_ci_checks(training_script):
    # already covered as continuous integration for ML code in this topic
    return "syntax error" not in training_script

def train_model(data_version):
    # already covered as automated training triggers in this topic
    return {"model_id": f"model_{data_version}", "accuracy": 0.91 if data_version == "v2" else 0.75}

def validation_gate(model, minimum_accuracy=0.85):
    # already covered as automated validation gates in this topic
    return model["accuracy"] >= minimum_accuracy

def deploy_pipeline(training_script, data_version, current_live_model):
    if not run_ci_checks(training_script):
        return current_live_model, "CI checks failed, pipeline stopped"

    new_model = train_model(data_version)
    if validation_gate(new_model):
        # already covered as continuous deployment to production in this topic
        return new_model, f"Deployed {new_model['model_id']}"
    else:
        # already covered as rollback on failure in this topic
        return current_live_model, f"Validation failed for {new_model['model_id']}, keeping current live model"

current_live_model = {"model_id": "model_v1", "accuracy": 0.80}
result_model, message = deploy_pipeline("clean training code", "v2", current_live_model)
print(f"Pipeline result (already covered in this topic): {message}")
print(f"Live model: {result_model}")
